/// <summary>
///     The <c>AVABPInfoUIBuilder</c> class is the execution class for <c>BP-Info</c>
/// </summary>
class AVABPInfoExecution
{
    Args                            args;
    KCS_KBVBuildingProjectID        argsKCS_KBVBuildingProjectID;
    KCS_KBVBuildingProjectTable     argsKCS_KBVBuildingProjectTable;

    AVABPInfoContract               contract;
    KCS_KBVBuildingProjectID        contractFromKCS_KBVBuildingProjectID;
    KCS_KBVBuildingProjectTable     contractFromKCS_KBVBuildingProjectTable;
    KCS_KBVBuildingProjectID        contractKCS_KBVBuildingProjectID;
    KCS_KBVBuildingProjectTable     contractKCS_KBVBuildingProjectTable;
    HcmWorkerRecId                  contractHCMWorkerRecId;
    HcmWorker                       contractHCMWorker;

    boolean                         lJobMode;

    KCS_KBVInfoTmp                  kbvInfoTmp;

    boolean                         deleteInfoTmpTable;

    int                             runtime;

    KCS_KBVParameters               kcs_KBVParameters;
    container                       allBPCompanies;
    container                       allBPCompaniesRicoIncluded;
    DataAreaId                      companyRico;
    container                       dataAreaIdContainerRICO;
    boolean                         dataAreaIdRicoExist;
    DataAreaId                      companyCurrent;
    container                       dataAreaIdContainerCurrent;

    AVABPInfoDateTime               kcs_MinDateTime;
    date                            kcs_MinDate;

    KCS_KBVBuildingProjectTable     kcs_KBVBuildingProjectTable;
    smmBusRelSalesDistrictGroup     smmBusRelSalesDistrictGroup;
    smmSalesUnit                    smmSalesUnit;
    smmResponsibilitiesEmplTable    smmResponsibilitiesEmplTable;

    boolean                         hcmWorkerEmailMissing;

    NDX_KBVEmailSend                logNDX_KBVEmailSend;


    #define.dataAreaIdRico('RIC')
    #define.dataAreaIdDat('DAT')

}

Method.Source:
/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVABPInfoController         locController;
    AVABPInfoContract           locContract;

    Common                      locCommon;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    locController   = AVABPInfoController::newFromArgs(_args);
    locController.parmLoadFromSysLastValue(NoYes::No);

    locContract     = locController.getDataContractObject();
    locContract.parmArgs(_args);

    if(     _args
        &&  _args.record()
        &&  _args.record().RecId
        &&  _args.record().TableId == tableNum(KCS_KBVBuildingProjectTable) )
    {
        locCommon = _args.record();

        if(_args.record().TableId == tableNum(KCS_KBVBuildingProjectTable))
        {
            locKCS_KBVBuildingProjectTable = locCommon;
        }
    }

    locController.startOperation();
}

/// <summary>
///    AVA <c>parmArgs</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = args)
{
    args = _parmValue;

    return args;
}

/// <summary>
///    AVA <c>parmDataContract</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>AVABPInfoContract</c> as type
/// </param>
/// <returns>
///    <c>AVABPInfoContract</c> as return value
/// </returns>
public AVABPInfoContract parmDataContract(AVABPInfoContract _parmValue = contract)
{
    contract = _parmValue;

    return contract;
}

/// <summary>
///    AVA <c>parmlJobMode</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean parmlJobMode(boolean _parmValue = lJobMode)
{
    lJobMode = _parmValue;

    return lJobMode;
}

/// <summary>
///    AVA <c>parmDeleteInfoTmpTable</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean parmDeleteInfoTmpTable(boolean _parmValue = deleteInfoTmpTable)
{
    deleteInfoTmpTable = _parmValue;

    return deleteInfoTmpTable;
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVABPInfoExecution</c> as return value
/// </returns>
public static AVABPInfoExecution newFromArgs(Args _args)
{
    AVABPInfoExecution locAVABPInfoExecution;

    locAVABPInfoExecution = new AVABPInfoExecution();
    locAVABPInfoExecution.parmArgs(_args);
    locAVABPInfoExecution.init();

    return locAVABPInfoExecution;
}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    Common  locCommon;

    if (args && args.record())
    {
        locCommon = args.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(KCS_KBVBuildingProjectTable))
        {
            argsKCS_KBVBuildingProjectTable = locCommon;
            argsKCS_KBVBuildingProjectID    = argsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
        }
        else
        {
            argsKCS_KBVBuildingProjectTable = null;
            argsKCS_KBVBuildingProjectID    = '';
        }
    }

    if(contract)
    {
        if(contract.parmHCMWorker())
        {
            contractHCMWorkerRecId              = contract.parmHCMWorker();
            contractHCMWorker                   = HCMWorker::find(contract.parmHCMWorker());
        }
        if(contract.parmFromKCS_KBVBuildingProjectID())
        {
            contractFromKCS_KBVBuildingProjectID    = contract.parmFromKCS_KBVBuildingProjectID();
            contractFromKCS_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable::find(contract.parmFromKCS_KBVBuildingProjectID());
            contractKCS_KBVBuildingProjectID        = contract.parmKCS_KBVBuildingProjectID();
            contractKCS_KBVBuildingProjectTable     = KCS_KBVBuildingProjectTable::find(contract.parmFromKCS_KBVBuildingProjectID());
        }

        deleteInfoTmpTable  = contract.parmRebuildData();
    }

    kcs_KBVParameters           = KCS_KBVParameters::find();
    allBPCompanies              = AVAKBVBuildingProjectHelper::getAllBPCompanies();

    companyCurrent              = curExt();
    dataAreaIdContainerCurrent  = [companyCurrent];

    companyRico                 = kcs_KBVParameters.AVADataAreaIdRICO;
    if(!companyRico)
    {
        companyRico                 = #dataAreaIdRico;
    }
    allBPCompaniesRicoIncluded  = AVAKBVBuildingProjectHelper::getAllBPCompanies();
    allBPCompaniesRicoIncluded  += companyRico;

    dataAreaIdContainerRICO     = [companyRico];
    if(CompanyInfo::findDataArea(companyRico))
    {
        dataAreaIdRicoExist     = true;
    }

    if(deleteInfoTmpTable)
    {
        this.deleteInfoTmpTable();
    }
}

/// <summary>
///    AVA <c>createTmpTableData</c> method.
/// </summary>
/// <param name="_deleteAllRecords">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean createTmpTableData(boolean _deleteAllRecords = false)
{
    boolean retVal;

    if(_deleteAllRecords)
    {
        this.deleteInfoTmpTable();
    }

    retVal = this.createInfoTmpTableData();

    return retVal;
}

/// <summary>
///    AVA <c>deleteInfoTmpTable</c> method.
/// </summary>
void deleteInfoTmpTable()
{
    ttsBegin;
    delete_from kbvInfoTmp;
    ttsCommit;
    /*
    if(dataAreaIdRicoExist && companyCurrent != companyRico)
    {
        changecompany(companyRico)
        {
            KCS_KBVInfoTmp  locKCS_KBVInfoTmpChangeCompany;

            ttsBegin;
            delete_from locKCS_KBVInfoTmpChangeCompany;
            ttsCommit;
        }
    }
    */
}

/// <summary>
///    AVA <c>createInfoTmpTableData</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
boolean createInfoTmpTableData() // 2009:KCS_KBVInfo.createTmpData2()
{
    if (!kcs_KBVParameters.RecId)
    {
        throw error("@NDX:NXABPParameterNotReadableNoResponsibilitieUpdate");
    }

    if(lJobMode)
    {
        kcs_MinDateTime = kcs_KBVParameters.NDX_KBVInfoDateTime;
    }
    else
    {
        kcs_MinDateTime = contract.parmStartDateTime();
    }

    kcs_MinDate = DateTimeUtil::date(kcs_MinDateTime);

    if(contract.parmIncludeNewBuildingProjects())
    {
        this.createInfoNewBuildingProjects();
    }

    if(contract.parmIncludeNewRequests())
    {
        this.createInfoNewRequests();
    }

    if(contract.parmIncludeNewRequestsRICO() && curExt() != companyRico)
    {
        if(dataAreaIdRicoExist)
        {
            changecompany(companyRico)
            {
                this.createInfoNewRequests();
            }
        }
    }

    if(contract.parmIncludeNewQuotations())
    {
        this.createInfoNewQuotations();
    }

    if(contract.parmIncludeChangedQuotations())
    {
        this.createInfoChangedQuotations();
    }

    if(contract.parmIncludeChangedBuildingProjects())
    {
        this.createInfoChangedBuildingProjects();
    }

    if(contract.parmNewChangedActivities())
    {
        this.createInfoNewChangedActivities();
    }

    if(contract.parmRebuildData())
    {
        this.updateParamterValues();
    }

    return true;
}

/// <summary>
///    AVA <c>updateParamterValues</c> method.
/// </summary>
void updateParamterValues()
{
    boolean             saveKBVInfoDateTime;
    NDX_KBVInfoDateTime locNDX_KBVInfoDateTime;

    saveKBVInfoDateTime = lJobMode;
    /* createdDateTime and modifiedDateTime not active on this table, so making no sense
    select firstonly createdDateTime
    from    kbvInfoTmp 
    order by RecId desc;

    locNDX_KBVInfoDateTime = kbvInfoTmp.createdDateTime;
    */

    locNDX_KBVInfoDateTime = DateTimeUtil::utcNow();

    if (!lJobMode)
    {
        saveKBVInfoDateTime = box::yesNo(strfmt("@NDX:NXADialogSaveLastBPInfoDataCreation", kcs_KBVParameters.NDX_KBVInfoDateTime, locNDX_KBVInfoDateTime), DialogButton::Yes) == DialogButton::Yes;
    }

    if (saveKBVInfoDateTime)
    {
        kcs_KBVParameters = KCS_KBVParameters::find(true);
        kcs_KBVParameters.NDX_KBVInfoDateTime = locNDX_KBVInfoDateTime;
        ttsbegin;
        kcs_KBVParameters.write();
        ttscommit;
    }

}

/// <summary>
///    AVA <c>createInfoNewBuildingProjects</c> method.
/// </summary>
void createInfoNewBuildingProjects()
{
    int         i;
    container   locCompanyContainer;
    DataAreaId  locDataAreaId;

    // create infos for new company specific records without any constraints
    while select kcs_KBVBuildingProjectTable
    where   (kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID   >= contractFromKCS_KBVBuildingProjectID || !contractFromKCS_KBVBuildingProjectID)
        &&  kcs_KBVBuildingProjectTable.createdDateTime             >= kcs_MinDateTime
        &&  kcs_KBVBuildingProjectTable.AddressCountryRegionId
        &&  kcs_KBVBuildingProjectTable.AddressZipCodeId
    {
        for (i = 1; i <= conlen(allBPCompanies); i++)
        {
            locDataAreaId       = conpeek(allBPCompanies, i);
            locCompanyContainer = connull();
            locCompanyContainer += locDataAreaId;

            smmBusRelSalesDistrictGroup = AVAKBVHelperClass::ZipCode2SalesDistrict( kcs_KBVBuildingProjectTable.AddressZipCodeId,
                                                                                    kcs_KBVBuildingProjectTable.AddressCountryRegionId,
                                                                                    locDataAreaId);

            if (!smmBusRelSalesDistrictGroup.RecId)
            {
                Warning(strfmt("@NDX:NXABPCannotFindSalesUnit", kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID, locDataAreaId));
            }
            else
            {
                smmSalesUnit = smmSalesUnit::AVAfind(   smmBusRelSalesDistrictGroup.KCS_KBVsmmSalesUnitId,
                                                        smmBusRelSalesDistrictGroup.dataAreaId  );
                if (smmSalesUnit.RecId)
                {
                    while select crosscompany : locCompanyContainer smmResponsibilitiesEmplTable
                    where   smmResponsibilitiesEmplTable.RefTableId == tablenum(smmSalesUnit)
                        &&  smmResponsibilitiesEmplTable.RefRecId   == smmSalesUnit.RecId
                    {
                        // prüfen, ob es schon einen Datensatz für den Zuständigen mit diesem Typ für dieses BV gibt
                        kbvInfoTmp = KCS_KBVInfoTmp::findGlobal(smmResponsibilitiesEmplTable.Worker,
                                                                kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                                KCS_KBVInfoArea::BVNew,
                                                                true                                                );
                        ttsbegin;
                        if (!kbvInfoTmp.recId)
                        {
                            kbvInfoTmp.clear();
                            kbvInfoTmp.KCS_KBVInfoArea                  = KCS_KBVInfoArea::BVNew;
                            kbvInfoTmp.KCS_KBVBuildingProjectID         = kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
                            kbvInfoTmp.AVAWorker                        = smmResponsibilitiesEmplTable.Worker;
                            kbvInfoTmp.KCS_KBVNewBuildingProject        = DateTimeUtil::date(kcs_KBVBuildingProjectTable.createdDateTime);
                            kbvInfoTmp.smmSalesUnitId                   = smmSalesUnit.SalesUnitId;
                            kbvInfoTmp.KCS_KBVInfoReason                = strFmt("@SYS82282", "@NDX:NXABPInLocalDistrict");
                            kbvInfoTmp.KCS_KBVDataArea                  = kcs_KBVBuildingProjectTable.dataAreaId; //locDataAreaId;
                            kbvInfoTmp.KCS_KBVDataAreas                 += locDataAreaId;
                            kbvInfoTmp.KCS_KBVDataAreasTxt              = AVAKBVBuildingProjectHelper::container2seperatedStr(kbvInfoTmp.KCS_KBVDataAreas);
                            kbvInfoTmp.insert();
                        }
                        else
                        {
                            if (!confind(kbvInfoTmp.KCS_KBVDataAreas, locDataAreaId))
                            {
                                kbvInfoTmp.KCS_KBVDataAreas     += locDataAreaId;
                                kbvInfoTmp.KCS_KBVDataAreasTxt  = AVAKBVBuildingProjectHelper::container2seperatedStr(kbvInfoTmp.KCS_KBVDataAreas);
                                kbvInfoTmp.update();
                            }
                            KCS_KBVInfoTmp::equalizeDataAreas(  smmResponsibilitiesEmplTable.Worker,
                                                                kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                                KCS_KBVInfoArea::BVNew,
                                                                smmSalesUnit.SalesUnitId                                );
                        }
                        ttscommit;
                    }
                }
            }
        }
    }
}

/// <summary>
///    AVA <c>createInfoNewRequests</c> method.
/// </summary>
void createInfoNewRequests()
//void NDX_createInfoNewRequests()
{
    KCS_KBVRequestTable kcs_KBVRequestTable;
    container           tempDataArea;
    DataAreaId          locDataAreaId;

    // create info for the responsibilities dedicated for the quotation (SQT.salesunitid)
    while select crosscompany : allBPCompaniesRicoIncluded kcs_KBVRequestTable
    where   (kcs_KBVRequestTable.KCS_KBVBuildingProjectID   >= contractFromKCS_KBVBuildingProjectID     || !contractFromKCS_KBVBuildingProjectID)
        &&  kcs_KBVRequestTable.KCS_KBVRequestStatus        == KCS_KBVRequestStatus::Created
        &&  kcs_KBVRequestTable.createdDateTime             >= kcs_MinDateTime
    {
        if(kcs_KBVRequestTable.dataAreaId == companyRico)
        {
            smmSalesUnit = this.requestResonsibleSalesUnit( kcs_KBVRequestTable.KCS_KBVBuildingProjectID, 
                                                            dataAreaIdContainerRICO                         );
        }
        else
        {
            smmSalesUnit = smmSalesUnit::AVAfind(   kcs_KBVRequestTable.KCS_KBVSmmSalesUnitIndoor,
                                                    kcs_KBVRequestTable.DataAreaId                  );
        }

        if (smmSalesUnit.RecId)
        {
            tempDataArea = connull();
            tempDataArea += kcs_KBVRequestTable.DataAreaId;
            locDataAreaId = kcs_KBVRequestTable.DataAreaId;

            while select crosscompany : tempDataArea smmResponsibilitiesEmplTable
            where   smmResponsibilitiesEmplTable.RefTableId == tablenum(smmSalesUnit)
                &&  smmResponsibilitiesEmplTable.RefRecId   == smmSalesUnit.RecId
            {
                // prüfen, ob es schon einen Datensatz für den Zuständigen mit diesem Typ für dieses BV gibt
                kbvInfoTmp = KCS_KBVInfoTmp::find(  smmResponsibilitiesEmplTable.Worker,
                                                    kcs_KBVRequestTable.KCS_KBVBuildingProjectID,
                                                    KCS_KBVInfoArea::RequestNew,
                                                    locDataAreaId,
                                                    smmSalesUnit.SalesUnitId,
                                                    true);
                ttsbegin;
                if (!kbvInfoTmp.recId)
                {
                    kbvInfoTmp.clear();
                    kbvInfoTmp.KCS_KBVInfoArea              = KCS_KBVInfoArea::RequestNew;

                    kbvInfoTmp.KCS_KBVBuildingProjectID     = kcs_KBVRequestTable.KCS_KBVBuildingProjectID;
                    kbvInfoTmp.AVAWorker                    = smmResponsibilitiesEmplTable.Worker;

                    kbvInfoTmp.NDX_KBVRequestID             = kcs_KBVRequestTable.KCS_KBVRequestID;
                    kbvInfoTmp.NDX_KBVNewRequest            = DateTimeUtil::date(kcs_KBVRequestTable.createdDateTime);

                    kbvInfoTmp.smmSalesUnitId               = smmSalesUnit.SalesUnitId;
                    kbvInfoTmp.KCS_KBVInfoReason            = strFmt("@SYS82282", "@NDX:NXADateNewQuotation");
                    kbvInfoTmp.KCS_KBVDataArea              = locDataAreaId;
                    kbvInfoTmp.KCS_KBVDataAreas             += locDataAreaId;
                    kbvInfoTmp.KCS_KBVDataAreasTxt          =  AVAKBVBuildingProjectHelper::container2seperatedStr(kbvInfoTmp.KCS_KBVDataAreas);
                    kbvInfoTmp.insert();
                }
                else
                {
                    if (!confind(kbvInfoTmp.KCS_KBVDataAreas, locDataAreaId))
                    {
                        kbvInfoTmp.KCS_KBVDataAreas     += locDataAreaId;
                        kbvInfoTmp.KCS_KBVDataAreasTxt  =  AVAKBVBuildingProjectHelper::container2seperatedStr(kbvInfoTmp.KCS_KBVDataAreas);
                        kbvInfoTmp.update();
                    }
                    KCS_KBVInfoTmp::equalizeDataAreas(  smmResponsibilitiesEmplTable.Worker,
                                                        kcs_KBVRequestTable.KCS_KBVBuildingProjectID,
                                                        KCS_KBVInfoArea::RequestNew,
                                                        smmSalesUnit.SalesUnitId                        );
                }
                ttscommit;
            }
        }
    }
}

/// <summary>
///    AVA <c>createInfoNewChangedActivities</c> method.
/// </summary>
void createInfoNewChangedActivities()
{
    KCS_KBVInfoArea             locKCS_KBVInfoArea;
    KCS_KBVActivitiesForBP      locKCS_KBVActivitiesForBP;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;
    smmActivities               locsmmActivities;
    KCS_KBVInfoTmp              locKCS_KBVInfoTmp;
    HcmWorkerRecId              locHCMWorkerRecId;
    str                         locChangeReason;

    locKCS_KBVInfoArea  = KCS_KBVInfoArea::ActivityNewChanged;

    while select crosscompany : allBPCompanies locKCS_KBVActivitiesForBP
    where   locKCS_KBVActivitiesForBP.createdDateTime >= kcs_MinDateTime
        join    locsmmActivities
        where   locsmmActivities.ActivityNumber     ==  locKCS_KBVActivitiesForBP.smmActivityNumber
            &&  locsmmActivities.Closed             == false
            &&  (   locsmmActivities.createdDateTime    >= kcs_MinDateTime 
                ||  locsmmActivities.modifiedDateTime   >= kcs_MinDateTime  )
        join    locKCS_KBVBuildingProjectTable
        where   locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID     == locKCS_KBVActivitiesForBP.KCS_KBVBuildingProjectID
            &&  (   locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID >= contractFromKCS_KBVBuildingProjectID
                ||  !contractFromKCS_KBVBuildingProjectID                                                           )
    {
        locChangeReason = strfmt("@SYS82282", "@NDX:NXABPChangesOnActivities");

        if(locSMMActivities.ResponsibleWorker || locSMMActivities.AVAFieldWorker)
        {
            if(locSMMActivities.ResponsibleWorker)
            {
                locHCMWorkerRecId = locSMMActivities.ResponsibleWorker;
                locKCS_KBVInfoTmp = KCS_KBVInfoTmp::find(   locHCMWorkerRecId,
                                                            locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                            locKCS_KBVInfoArea,
                                                            locKCS_KBVActivitiesForBP.DataAreaId,
                                                            //'',
                                                            locKCS_KBVBuildingProjectTable.smmSalesDistrictId,
                                                            true
                                                            );
                ttsbegin;

                if (!locKCS_KBVInfoTmp.recId)
                {
                    locKCS_KBVInfoTmp.clear();
                    locKCS_KBVInfoTmp.KCS_KBVInfoArea              = locKCS_KBVInfoArea;
                    locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID     = locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
                    locKCS_KBVInfoTmp.AVAWorker                    = locHCMWorkerRecId;
                    locKCS_KBVInfoTmp.smmSalesUnitId               = locKCS_KBVBuildingProjectTable.smmSalesDistrictId;
                    locKCS_KBVInfoTmp.KCS_KBVInfoReason            = locChangeReason;
                    locKCS_KBVInfoTmp.KCS_KBVDataArea              = locKCS_KBVActivitiesForBP.dataAreaId;
                    locKCS_KBVInfoTmp.KCS_KBVDataAreas             += locKCS_KBVActivitiesForBP.dataAreaId;
                    locKCS_KBVInfoTmp.KCS_KBVDataAreasTxt          = AVAKBVBuildingProjectHelper::container2seperatedStr(locKCS_KBVInfoTmp.KCS_KBVDataAreas);
                    locKCS_KBVInfoTmp.insert();
                }
                else
                {
                    if (!strscan(locKCS_KBVInfoTmp.KCS_KBVInfoReason, locChangeReason, 1, strlen(locKCS_KBVInfoTmp.KCS_KBVInfoReason)))
                    {
                        locKCS_KBVInfoTmp.KCS_KBVInfoReason += locChangeReason;
                    }
                    if (!confind(locKCS_KBVInfoTmp.KCS_KBVDataAreas, locKCS_KBVActivitiesForBP.dataAreaId))
                    {
                        locKCS_KBVInfoTmp.KCS_KBVDataAreas  += locKCS_KBVActivitiesForBP.dataAreaId;
                    }
                    locKCS_KBVInfoTmp.KCS_KBVDataAreasTxt   = AVAKBVBuildingProjectHelper::container2seperatedStr(locKCS_KBVInfoTmp.KCS_KBVDataAreas);
                    locKCS_KBVInfoTmp.update();
                }

                ttscommit;
            }
            if(locSMMActivities.AVAFieldWorker && locSMMActivities.AVAFieldWorker != locSMMActivities.ResponsibleWorker)
            {
                locHCMWorkerRecId = locSMMActivities.AVAFieldWorker;
                locKCS_KBVInfoTmp = KCS_KBVInfoTmp::find(   locHCMWorkerRecId,
                                                            locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                            locKCS_KBVInfoArea,
                                                            locKCS_KBVActivitiesForBP.DataAreaId,
                                                            '',
                                                            true
                                                            );
                ttsbegin;

                if (!locKCS_KBVInfoTmp.recId)
                {
                    locKCS_KBVInfoTmp.clear();
                    locKCS_KBVInfoTmp.KCS_KBVInfoArea              = locKCS_KBVInfoArea;
                    locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID     = locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
                    locKCS_KBVInfoTmp.AVAWorker                    = locHCMWorkerRecId;
                    locKCS_KBVInfoTmp.smmSalesUnitId               = locKCS_KBVBuildingProjectTable.smmSalesDistrictId;
                    locKCS_KBVInfoTmp.KCS_KBVInfoReason            = locChangeReason;
                    locKCS_KBVInfoTmp.KCS_KBVDataArea              = locKCS_KBVActivitiesForBP.dataAreaId;
                    locKCS_KBVInfoTmp.KCS_KBVDataAreas             += locKCS_KBVActivitiesForBP.dataAreaId;
                    locKCS_KBVInfoTmp.KCS_KBVDataAreasTxt          = AVAKBVBuildingProjectHelper::container2seperatedStr(locKCS_KBVInfoTmp.KCS_KBVDataAreas);
                    locKCS_KBVInfoTmp.insert();
                }
                else
                {
                    if (!strscan(locKCS_KBVInfoTmp.KCS_KBVInfoReason, locChangeReason, 1, strlen(locKCS_KBVInfoTmp.KCS_KBVInfoReason)))
                    {
                        locKCS_KBVInfoTmp.KCS_KBVInfoReason += locChangeReason;
                    }
                    if (!confind(locKCS_KBVInfoTmp.KCS_KBVDataAreas, locKCS_KBVActivitiesForBP.dataAreaId))
                    {
                        locKCS_KBVInfoTmp.KCS_KBVDataAreas  += locKCS_KBVActivitiesForBP.dataAreaId;
                    }
                    locKCS_KBVInfoTmp.KCS_KBVDataAreasTxt   = AVAKBVBuildingProjectHelper::container2seperatedStr(locKCS_KBVInfoTmp.KCS_KBVDataAreas);
                    locKCS_KBVInfoTmp.update();
                }

                ttscommit;
            }
        }
    }
}

/// <summary>
///    AVA <c>requestResonsibleSalesUnit</c> method.
/// </summary>
/// <param name="_fromKCS_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_dataAreaIdContainer">
///    <c>container</c> as type
/// </param>
/// <returns>
///    <c>smmSalesUnit</c> as return value
/// </returns>
smmSalesUnit requestResonsibleSalesUnit(KCS_KBVBuildingProjectID    _fromKCS_KBVBuildingProjectID, 
                                        container                   _dataAreaIdContainer            )
{
    smmSalesUnit retVal;

    KCS_KBVRequestTable locKCS_KBVRequestTable;

    select firstonly crosscompany : _dataAreaIdContainer locKCS_KBVRequestTable
    order by locKCS_KBVRequestTable.KCS_KBVRequestID
    where locKCS_KBVRequestTable.KCS_KBVBuildingProjectID == _fromKCS_KBVBuildingProjectID;

    if(locKCS_KBVRequestTable.RecId)
    {
        retVal = smmSalesUnit::AVAfind( locKCS_KBVRequestTable.KCS_KBVSmmSalesUnitIndoor,
                                        locKCS_KBVRequestTable.dataAreaId   );
    }
    return retVal;
}

/// <summary>
///    AVA <c>createInfoNewQuotations</c> method.
/// </summary>
void createInfoNewQuotations()
{
    SalesQuotationTable locSalesQuotationTable;
    container           locDataAreaIdContainer;
    DataAreaId          locDataAreaId;

    while select crosscompany : allBPCompanies locSalesQuotationTable
    where   (locSalesQuotationTable.KCS_KBVBuildingProjectID  >= contractFromKCS_KBVBuildingProjectID || !contractFromKCS_KBVBuildingProjectID)
        &&  locSalesQuotationTable.QuotationStatus != SalesQuotationStatus::Created
        &&  locSalesQuotationTable.createdDateTime >= kcs_MinDateTime
        &&  locSalesQuotationTable.SalesUnitId     != ''
    {
        smmSalesUnit = smmSalesUnit::AVAfind(   locSalesQuotationTable.SalesUnitId,
                                                locSalesQuotationTable.DataAreaId);
        if (smmSalesUnit.RecId)
        {
            locDataAreaIdContainer  = connull();
            locDataAreaIdContainer  += locSalesQuotationTable.DataAreaId;
            locDataAreaId           = locSalesQuotationTable.DataAreaId;

            while select crosscompany : locDataAreaIdContainer smmResponsibilitiesEmplTable
            where   smmResponsibilitiesEmplTable.RefTableId == tablenum(smmSalesUnit)
                &&  smmResponsibilitiesEmplTable.RefRecId   == smmSalesUnit.RecId
            {
                // prüfen, ob es schon einen Datensatz für den Zuständigen mit diesem Typ für dieses BV und der Verkaufseinheit gibt
                kbvInfoTmp = KCS_KBVInfoTmp::find(  smmResponsibilitiesEmplTable.Worker,
                                                    locSalesQuotationTable.KCS_KBVBuildingProjectID,
                                                    KCS_KBVInfoArea::QuotationNew,
                                                    locDataAreaId,
                                                    smmSalesUnit.SalesUnitId,
                                                    true                                            );
                ttsbegin;
                if (!kbvInfoTmp.RecId)
                {
                    kbvInfoTmp.clear();
                    kbvInfoTmp.KCS_KBVInfoArea          = KCS_KBVInfoArea::QuotationNew;
                    kbvInfoTmp.KCS_KBVBuildingProjectID = locSalesQuotationTable.KCS_KBVBuildingProjectID;
                    kbvInfoTmp.AVAWorker                = smmResponsibilitiesEmplTable.Worker;
                    kbvInfoTmp.KCS_KBVNewQuotation      = DateTimeUtil::date(locSalesQuotationTable.createdDateTime);
                    kbvInfoTmp.smmSalesUnitId           = smmSalesUnit.SalesUnitId;
                    kbvInfoTmp.KCS_KBVInfoReason        = strFmt("@SYS82282", "@NDX:NXADateNewQuotation");
                    kbvInfoTmp.KCS_KBVDataArea          = locDataAreaId;
                    kbvInfoTmp.KCS_KBVDataAreas         += locDataAreaId;
                    kbvInfoTmp.KCS_KBVDataAreasTxt      = AVAKBVBuildingProjectHelper::container2seperatedStr(kbvInfoTmp.KCS_KBVDataAreas);
                    kbvInfoTmp.insert();
                }
                else
                {
                    if (!confind(kbvInfoTmp.KCS_KBVDataAreas, locDataAreaId))
                    {
                        kbvInfoTmp.KCS_KBVDataAreas     += locDataAreaId;
                        kbvInfoTmp.KCS_KBVDataAreasTxt  = AVAKBVBuildingProjectHelper::container2seperatedStr(kbvInfoTmp.KCS_KBVDataAreas);
                        kbvInfoTmp.update();
                    }
                }
                KCS_KBVInfoTmp::equalizeDataAreas(  smmResponsibilitiesEmplTable.Worker,
                                                    locSalesQuotationTable.KCS_KBVBuildingProjectID,
                                                    KCS_KBVInfoArea::QuotationNew,
                                                    smmSalesUnit.SalesUnitId                        );
                ttscommit;
            }
        }
    }
}

/// <summary>
///    AVA <c>createInfoChangedQuotations</c> method.
/// </summary>
void createInfoChangedQuotations()
{
    SalesQuotationTable         locSalesQuotationTable;
    CustQuotationSalesLink      locCustQuotationSalesLinkLast;
    CustQuotationJour           locCustQuotationJourLast;
    CustQuotationSalesLink      locCustQuotationSalesLinkFirst;
    CustQuotationJour           locCustQuotationJourFirst;

    container                   locDataAreaIdContainer;
    DataAreaId                  locDataAreaId;

    date                        locKCS_MinDate;
    AVABPInfoDateTime           locKCS_MinDateTime;

    locKCS_MinDateTime  = kcs_MinDateTime;
    locKCS_MinDate      = DateTimeUtil::date(locKCS_MinDateTime);

    // create info for changed quotations
    while select crosscompany : allBPCompanies locCustQuotationSalesLinkLast
    order by QuotationDate desc, QuotationId desc
        join    locCustQuotationJourLast
        where   locCustQuotationJourLast.QuotationId        == locCustQuotationSalesLinkLast.QuotationId
            &&  locCustQuotationJourLast.QuotationDate      == locCustQuotationSalesLinkLast.QuotationDate
            &&  locCustQuotationJourLast.SalesId            == locCustQuotationSalesLinkLast.SalesId
            &&  locCustQuotationJourLast.createdDateTime    >= locKCS_MinDateTime
            //&&  locCustQuotationJourLast.QuotationDate      >= locKCS_MinDate
    {
        locDataAreaIdContainer  = connull();
        locDataAreaIdContainer  += locCustQuotationSalesLinkLast.dataAreaId;

        select firstonly crosscompany : locDataAreaIdContainer locCustQuotationSalesLinkFirst
        order by QuotationDate, QuotationId
        where locCustQuotationSalesLinkFirst.origQuotationId    == locCustQuotationJourLast.KCS_QuotationId
            join    locCustQuotationJourFirst
            where   locCustQuotationJourFirst.QuotationId       == locCustQuotationSalesLinkFirst.QuotationId
                &&  locCustQuotationJourFirst.QuotationDate     == locCustQuotationSalesLinkFirst.QuotationDate
                &&  locCustQuotationJourFirst.SalesId           == locCustQuotationSalesLinkFirst.salesId
                &&  locCustQuotationJourFirst.createdDateTime   < locKCS_MinDateTime;
                //&&  locCustQuotationJourFirst.QuotationDate     < locKCS_MinDate;

        if (locCustQuotationJourFirst.RecId)
        {
            select firstOnly crosscompany : locDataAreaIdContainer locSalesQuotationTable
            where   locSalesQuotationTable.QuotationId                  == locCustQuotationSalesLinkLast.OrigQuotationId
                &&  (locSalesQuotationTable.KCS_KBVBuildingProjectID    >= contractFromKCS_KBVBuildingProjectID || !contractFromKCS_KBVBuildingProjectID)
                &&  locSalesQuotationTable.KCS_KBVBuildingProjectID     != ''
                &&  locSalesQuotationTable.SalesUnitId                  != ''
                &&  locSalesQuotationTable.createdDateTime              < locKCS_MinDateTime;

            if (locSalesQuotationTable.recId)
            {
                smmSalesUnit = smmSalesUnit::AVAfind(locSalesQuotationTable.SalesUnitId, locSalesQuotationTable.dataAreaId);
                if (smmSalesUnit.RecId)
                {
                    locDataAreaId = locSalesQuotationTable.dataAreaId;

                    while select crosscompany : locDataAreaIdContainer smmResponsibilitiesEmplTable
                    where   smmResponsibilitiesEmplTable.RefTableId == tablenum(smmSalesUnit)
                        &&  smmResponsibilitiesEmplTable.RefRecId   == smmSalesUnit.RecId
                    {
                        // prüfen, ob es schon einen Datensatz für den Zuständigen mit diesem Typ für dieses BV und der Verkaufseinheit gibt
                        kbvInfoTmp = KCS_KBVInfoTmp::find(  smmResponsibilitiesEmplTable.Worker,
                                                            locSalesQuotationTable.KCS_KBVBuildingProjectID,
                                                            KCS_KBVInfoArea::QuotationChanged,
                                                            locDataAreaId,
                                                            smmSalesUnit.SalesUnitId,
                                                            true                                            );
                        ttsbegin;

                        if (!kbvInfoTmp.recId)
                        {
                            kbvInfoTmp.clear();
                            kbvInfoTmp.KCS_KBVInfoArea          = KCS_KBVInfoArea::QuotationChanged;
                            kbvInfoTmp.KCS_KBVBuildingProjectID = locSalesQuotationTable.KCS_KBVBuildingProjectID;
                            kbvInfoTmp.AVAWorker                = smmResponsibilitiesEmplTable.Worker;
                            kbvInfoTmp.KCS_KBVNewQuotation      = DateTimeUtil::date(locSalesQuotationTable.createdDateTime);
                            kbvInfoTmp.smmSalesUnitId           = smmSalesUnit.SalesUnitId;
                            kbvInfoTmp.KCS_KBVInfoReason        = strFmt("@SYS82282", "@NDX:NXAChangedVersionOfQuotation");
                            kbvInfoTmp.KCS_KBVDataArea          = locDataAreaId;
                            kbvInfoTmp.KCS_KBVDataAreas         += locDataAreaId;
                            kbvInfoTmp.KCS_KBVDataAreasTxt      = AVAKBVBuildingProjectHelper::container2seperatedStr(kbvInfoTmp.KCS_KBVDataAreas);
                            kbvInfoTmp.insert();
                        }
                        else
                        {
                            if (!confind(kbvInfoTmp.KCS_KBVDataAreas, locDataAreaId))
                            {
                                kbvInfoTmp.KCS_KBVDataAreas     += locDataAreaId;
                                kbvInfoTmp.KCS_KBVDataAreasTxt  = AVAKBVBuildingProjectHelper::container2seperatedStr(kbvInfoTmp.KCS_KBVDataAreas);
                                kbvInfoTmp.update();
                            }
                        }
                        KCS_KBVInfoTmp::equalizeDataAreas(  smmResponsibilitiesEmplTable.Worker,
                                                            locSalesQuotationTable.KCS_KBVBuildingProjectID,
                                                            KCS_KBVInfoArea::QuotationChanged,
                                                            smmSalesUnit.SalesUnitId                        );
                       ttscommit;
                    }
                }
            }
        }
    }

    // Änderungen am Angebotskopf auch überprüfen
    while select crosscompany : allBPCompanies locSalesQuotationTable
    where   locSalesQuotationTable.KCS_KBVBuildingProjectID     != ''
        &&  (locSalesQuotationTable.KCS_KBVBuildingProjectID    >= contractFromKCS_KBVBuildingProjectID || !contractFromKCS_KBVBuildingProjectID)
        &&  locSalesQuotationTable.QuotationStatus              != SalesQuotationStatus::Created
        &&  locSalesQuotationTable.modifiedDateTime             >= locKCS_MinDateTime
        &&  locSalesQuotationTable.createdDateTime              < locKCS_MinDateTime
    {
        smmSalesUnit = smmSalesUnit::AVAfind(locSalesQuotationTable.SalesUnitId, locSalesQuotationTable.dataAreaId);
        if (smmSalesUnit.RecId)
        {
            locDataAreaId           = locSalesQuotationTable.dataAreaId;
            locDataAreaIdContainer  = connull();
            locDataAreaIdContainer  += locDataAreaId;

            while select crosscompany : locDataAreaIdContainer * from smmResponsibilitiesEmplTable
            where   smmResponsibilitiesEmplTable.RefTableId == tablenum(smmSalesUnit) &&
                    smmResponsibilitiesEmplTable.RefRecId   == smmSalesUnit.RecId
            {
                // prüfen, ob es schon einen Datensatz für den Zuständigen mit diesem Typ für dieses BV gibt
                kbvInfoTmp = KCS_KBVInfoTmp::find(  smmResponsibilitiesEmplTable.Worker,
                                                    locSalesQuotationTable.KCS_KBVBuildingProjectID,
                                                    KCS_KBVInfoArea::QuotationChanged,
                                                    locDataAreaId,
                                                    smmSalesUnit.SalesUnitId,
                                                    true    );
                ttsbegin;

                if (!kbvInfoTmp.recId)
                {
                    kbvInfoTmp.clear();
                    kbvInfoTmp.KCS_KBVInfoArea              = KCS_KBVInfoArea::QuotationChanged;
                    kbvInfoTmp.KCS_KBVBuildingProjectID     = locSalesQuotationTable.KCS_KBVBuildingProjectID;
                    kbvInfoTmp.AVAWorker                    = smmResponsibilitiesEmplTable.Worker;
                    kbvInfoTmp.KCS_KBVNewQuotation          = DateTimeUtil::date(locSalesQuotationTable.createdDateTime);
                    kbvInfoTmp.smmSalesUnitId               = smmSalesUnit.SalesUnitId;
                    kbvInfoTmp.KCS_KBVInfoReason            = strFmt("@SYS82282", "@NDX:NXAQuotationHeaderChanged");
                    kbvInfoTmp.KCS_KBVDataArea              = locDataAreaId;
                    kbvInfoTmp.KCS_KBVDataAreas             += locDataAreaId;
                    kbvInfoTmp.KCS_KBVDataAreasTxt          = AVAKBVBuildingProjectHelper::container2seperatedStr(kbvInfoTmp.KCS_KBVDataAreas);
                    kbvInfoTmp.insert();
                }
                else
                {
                    if (!confind(kbvInfoTmp.KCS_KBVDataAreas, locDataAreaId))
                    {
                        kbvInfoTmp.KCS_KBVDataAreas     += locDataAreaId;
                        kbvInfoTmp.KCS_KBVDataAreasTxt  = AVAKBVBuildingProjectHelper::container2seperatedStr(kbvInfoTmp.KCS_KBVDataAreas);
                        kbvInfoTmp.update();
                    }
                }
                KCS_KBVInfoTmp::equalizeDataAreas(  smmResponsibilitiesEmplTable.Worker,
                                                    locSalesQuotationTable.KCS_KBVBuildingProjectID,
                                                    KCS_KBVInfoArea::QuotationChanged,
                                                    smmSalesUnit.SalesUnitId                        );
                ttscommit;
            }
        }
    }
}

/// <summary>
///    AVA <c>createInfoChangedBuildingProjects</c> method.
/// </summary>
void createInfoChangedBuildingProjects()
{
    KCS_DirProductGroupAddressRanking   kcs_DirProductGroupAddressRanking;
    KCS_KBVRelationsToBV                kcs_KBVRelationsToBV;
    smmActivityParentLinkTable          smmActivityParentLinkTable;
    smmActivities                       smmActivities;
    KCS_KBVResponsibilitiesTable        kcs_KBVResponsibilitiesTable;
    //KCS_KBVInfoTmp                      kcs_KBVInfoTmp;

    str                                 changeReason;

    //Änderungen direkt am Bauvorhaben
    while select kcs_KBVBuildingProjectTable
    where   (kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID   >= contractFromKCS_KBVBuildingProjectID || !contractFromKCS_KBVBuildingProjectID)
        &&  kcs_KBVBuildingProjectTable.modifiedDateTime            >= kcs_MinDateTime
    {
        changeReason = strfmt("@SYS82282" + '#', "@NDX:NXABPChangesOnBuildingProjects");
        KCS_KBVInfoTmp::addKBVInfoTmp(  kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                        kcs_MinDate,
                                        KCS_KBVInfoArea::BVChanged,
                                        kcs_KBVBuildingProjectTable.smmSalesDistrictId,
                                        changeReason);
    }

    // Änderungen an den Mitbewerbern
    while select kcs_DirProductGroupAddressRanking
    where   kcs_DirProductGroupAddressRanking.DirProdGroupAddressType   == KCS_DirProdGroupAddressType::KBVBuildingProject
        // 2009: &&  (kcs_DirProductGroupAddressRanking.CustPartyId >= contractFromKCS_KBVBuildingProjectID || !contractFromKCS_KBVBuildingProjectID)
        &&  (kcs_DirProductGroupAddressRanking.KCS_KBVBuildingProjectID >= contractFromKCS_KBVBuildingProjectID || !contractFromKCS_KBVBuildingProjectID)
        &&  kcs_DirProductGroupAddressRanking.modifiedDateTime          >= kcs_MinDateTime
    {
        changeReason = strfmt("@SYS82282" + '#', "@NDX:NXABPChangesOnCompetitors");
        // 2009: KCS_KBVInfoTmp::addKBVInfoTmp(  kcs_DirProductGroupAddressRanking.CustPartyId,
        KCS_KBVInfoTmp::addKBVInfoTmp(  kcs_DirProductGroupAddressRanking.KCS_KBVBuildingProjectID,
                                        kcs_MinDate,
                                        KCS_KBVInfoArea::BVChanged,
                                        // 2009: KCS_KBVBuildingProjectTable::find(kcs_DirProductGroupAddressRanking.CustPartyId).smmSalesDistrictId,
                                        KCS_KBVBuildingProjectTable::find(kcs_DirProductGroupAddressRanking.KCS_KBVBuildingProjectID).smmSalesDistrictId,
                                        changeReason);
    }

    // Änderungen an den Beziehungen
    while select kcs_KBVRelationsToBV
    where   (kcs_KBVRelationsToBV.KCS_KBVBuildingProjectID  >= contractFromKCS_KBVBuildingProjectID || !contractFromKCS_KBVBuildingProjectID)
        &&  kcs_KBVRelationsToBV.modifiedDateTime           >= kcs_MinDateTime
    {
        changeReason = strfmt("@SYS82282" + '#', "@NDX:NXABPChangesOnRelations");
        KCS_KBVInfoTmp::addKBVInfoTmp(  kcs_KBVRelationsToBV.KCS_KBVBuildingProjectID,
                                        kcs_MinDate,
                                        KCS_KBVInfoArea::BVChanged,
                                        KCS_KBVBuildingProjectTable::find(kcs_KBVRelationsToBV.KCS_KBVBuildingProjectID).smmSalesDistrictId,
                                        changeReason);
    }

    // Änderungen an den Zuständigkeiten
    while select crosscompany : allBPCompanies kcs_KBVResponsibilitiesTable
    where   (kcs_KBVResponsibilitiesTable.KCS_KBVBuildingProjectID  >= contractFromKCS_KBVBuildingProjectID || !contractFromKCS_KBVBuildingProjectID)
        &&  (kcs_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate  == DateNull() || kcs_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate >= kcs_MinDate)
        &&  kcs_KBVResponsibilitiesTable.modifiedDateTime           >= kcs_MinDateTime
    {
        changeReason = strfmt("@SYS82282" + '#', "@NDX:NXABPChangesOnResponsibilities");
        KCS_KBVInfoTmp::addKBVInfoTmp(  kcs_KBVResponsibilitiesTable.KCS_KBVBuildingProjectID,
                                        kcs_MinDate,
                                        KCS_KBVInfoArea::BVChanged,
                                        KCS_KBVBuildingProjectTable::find(kcs_KBVResponsibilitiesTable.KCS_KBVBuildingProjectID).smmSalesDistrictId,
                                        changeReason);
    }

    // Änderungen an den Aktivitäten
    while select crosscompany : allBPCompanies smmActivityParentLinkTable
    where   smmActivityParentLinkTable.ParentType   == smmActivityParentType::BuildingProject
        join    smmActivities
        where   smmActivities.ActivityNumber        == smmActivityParentLinkTable.ActivityNumber
            &&  smmActivities.Closed                == false
            &&  smmActivities.modifiedDateTime      >= kcs_MinDateTime
        join    kcs_KBVBuildingProjectTable
        where   kcs_KBVBuildingProjectTable.RecId   == smmActivityParentLinkTable.RefRecId
            &&  (kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID >= contractFromKCS_KBVBuildingProjectID || !contractFromKCS_KBVBuildingProjectID)
    {
        changeReason = strfmt("@SYS82282" + '#', "@NDX:NXABPChangesOnActivities");
        KCS_KBVInfoTmp::addKBVInfoTmp(  kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                        kcs_MinDate,
                                        KCS_KBVInfoArea::BVChanged,
                                        kcs_KBVBuildingProjectTable.smmSalesDistrictId,
                                        changeReason);
    }

    // ToDo: Check this.NDX_AddKBVInfoTmp();
}

/// <summary>
///    AVA <c>sendBPInfoCheck</c> method.
/// </summary>
/// <param name="_kcs_KBVInfoArea">
///    <c>KCS_KBVInfoArea</c> as type
/// </param>
/// <param name="_hcmWorker">
///    <c>HcmWorker</c> as type
/// </param>
/// <param name="_dataAreaId">
///    <c>DataAreaId</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
boolean sendBPInfoCheck(KCS_KBVInfoArea _kcs_KBVInfoArea,
                        HcmWorker       _hcmWorker,
                        DataAreaId      _dataAreaId         = '')
{
    boolean                         retVal;

    KCS_KBVInfoTmp                  locKCS_KBVInfoTmp;
    KCS_KBVPotentialSalesVolumeGLB  lockCS_KBVPotentialSalesVolumeGLB;

    switch(_kcs_KBVInfoArea)
    {
        case KCS_KBVInfoArea::BVNew:
        case KCS_KBVInfoArea::QuotationNew:
        case KCS_KBVInfoArea::QuotationChanged:
        case KCS_KBVInfoArea::BVChanged:
            select firstOnly1 locKCS_KBVInfoTmp
            where   locKCS_KBVInfoTmp.AVAWorker        == _hcmWorker.RecId
                &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea  == _kcs_KBVInfoArea
                join    locKCS_KBVPotentialSalesVolumeGLB
                where   locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVBuildingProjectID      == locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID
                    &&  locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume   >= _hcmWorker.NDX_KBVInfoRevLimit;
            if(locKCS_KBVInfoTmp.RecId)
            {
                if(_hcmWorker.email() == '')
                {
                    hcmWorkerEmailMissing = true;
                }
                retVal = true;
            }
            break;

        case KCS_KBVInfoArea::RequestNew: // used as well for RICO
            if(dataAreaIdRicoExist && _dataAreaId == companyRico)
            {
                select firstOnly1 crosscompany : dataAreaIdContainerRICO locKCS_KBVInfoTmp
                where   locKCS_KBVInfoTmp.AVAWorker        == _hcmWorker.RecId
                    &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea  == _kcs_KBVInfoArea;
                if(locKCS_KBVInfoTmp.RecId)
                {
                    if(_hcmWorker.email() == '')
                    {
                        hcmWorkerEmailMissing = true;
                    }
                    retVal = true;
                }
            }
            else
            {
                select firstOnly1 locKCS_KBVInfoTmp
                where   locKCS_KBVInfoTmp.AVAWorker        == _hcmWorker.RecId
                    &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea  == _kcs_KBVInfoArea;
                if(locKCS_KBVInfoTmp.RecId)
                {
                    if(_hcmWorker.email() == '')
                    {
                        hcmWorkerEmailMissing = true;
                    }
                    retVal = true;
                }
            }
            break;

        default:
            if(contract.parmNewChangedActivities() && _hcmWorker.NDX_KBVSendActivities)
            {
                if(_hcmWorker.email() == '')
                {
                    hcmWorkerEmailMissing = true;
                }
                // nothing to check
                retVal = true;
            }
    }
    return retVal;
}

/// <summary>
///    AVA <c>sendBPInfo</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
boolean sendBPInfo()  // 2009: KCS_KBVInfo.printKBVInfoTmp()
{
    boolean retVal;

    HcmWorker       locHCMWorker;
    Email           locHCMWorkerEmail;

    KCS_KBVInfoArea locKCS_KBVInfoArea;

    if(     !contract.parmIncludeNewBuildingProjects()
        &&  !contract.parmIncludeNewRequests()
        &&  !contract.parmIncludeNewRequestsRICO()
        &&  !contract.parmIncludeNewQuotations()
        &&  !contract.parmIncludeChangedQuotations()
        &&  !contract.parmIncludeChangedBuildingProjects()
        &&  !contract.parmNewChangedActivities()            )
    {
        return true;
    }

    retVal = true;

    while select locHCMWorker
    /*
    where   locHCMWorker.KCS_KBVInfoType        != KCS_KBVInfoType::Nothing
        &&  (locHCMWorker.RecId                 == contractHCMWorkerRecId || !contractHCMWorkerRecId)
        &&  locHCMWorker.KCS_KBVAutoActivity    == NoYes::Yes
    */
    where   (locHCMWorker.RecId                 == contractHCMWorkerRecId || !contractHCMWorkerRecId)
        &&  locHCMWorker.KCS_KBVAutoActivity    == NoYes::Yes
    {
        locHCMWorkerEmail       = locHCMWorker.email();
        hcmWorkerEmailMissing   = false;

        if(locHCMWorkerEmail || contract.parmTestEmailTo())  // sending email possible at least for test emails with info message when missing email address 
        {
            // NEW BUILDING PROJECTS
            if(contract.parmIncludeNewBuildingProjects())
            {
                locKCS_KBVInfoArea = KCS_KBVInfoArea::BVNew;

                if(this.sendBPInfoCheck(locKCS_KBVInfoArea, locHCMWorker))
                {
                    this.prepareEmailContent(locKCS_KBVInfoArea, locHCMWorker);
                }
            }

            // NEW REQUESTS
            if(     locHCMWorker.NDX_KBVAutoActivityRequests == NoYes::Yes
                &&  contract.parmIncludeNewRequests()                       )
            {
                locKCS_KBVInfoArea = KCS_KBVInfoArea::RequestNew;

                if(this.sendBPInfoCheck(locKCS_KBVInfoArea, locHCMWorker))
                {
                    this.prepareEmailContent(locKCS_KBVInfoArea, locHCMWorker);
                }
            }

            // NEW RICO REQUESTS
            if(     curExt() != companyRico
                &&  locHCMWorker.NDX_KBVAutoActivityRequests == NoYes::Yes
                &&  contract.parmIncludeNewRequestsRICO()                   )
            {
                if(dataAreaIdRicoExist)
                {
                    locKCS_KBVInfoArea = KCS_KBVInfoArea::RequestNew;

                    if(this.sendBPInfoCheck(locKCS_KBVInfoArea, locHCMWorker, companyRico))
                    {
                        this.prepareEmailContent(locKCS_KBVInfoArea, locHCMWorker, companyRico);
                    }
                }
            }

            // NEW QUOTATIONS
            if(contract.parmIncludeNewQuotations())
            {
                locKCS_KBVInfoArea = KCS_KBVInfoArea::QuotationNew;

                if(this.sendBPInfoCheck(locKCS_KBVInfoArea, locHCMWorker))
                {
                    this.prepareEmailContent(locKCS_KBVInfoArea, locHCMWorker);
                }
            }

            // CHANGED QUOTATIONS
            if(contract.parmIncludeChangedQuotations())
            {
                locKCS_KBVInfoArea = KCS_KBVInfoArea::QuotationChanged;

                if(this.sendBPInfoCheck(locKCS_KBVInfoArea, locHCMWorker))
                {
                    this.prepareEmailContent(locKCS_KBVInfoArea, locHCMWorker);
                }
            }

            // CHANGED BUILDING PROJECTS
            if(contract.parmIncludeChangedBuildingProjects())
            {
                locKCS_KBVInfoArea = KCS_KBVInfoArea::BVChanged;

                if(this.sendBPInfoCheck(locKCS_KBVInfoArea, locHCMWorker))
                {
                    this.prepareEmailContent(locKCS_KBVInfoArea, locHCMWorker);
                }
            }

            // ACTIVITIES
            if(     locHCMWorker.NDX_KBVSendActivities  == NoYes::Yes
                &&  contract.parmNewChangedActivities()                 )
            {
                locKCS_KBVInfoArea = KCS_KBVInfoArea::ActivityNewChanged;

                if(this.sendBPInfoCheck(locKCS_KBVInfoArea, locHCMWorker))
                {
                    this.prepareEmailContent(locKCS_KBVInfoArea, locHCMWorker);
                }
            }
        }
        if(hcmWorkerEmailMissing)
        {
            info(strFmt("@NDX:NXAEmailAddressMissingForWorker", locHCMWorker.name()));
        }
    }
    return retVal;
}

/// <summary>
///    AVA <c>prepareEmailContent</c> method.
/// </summary>
/// <param name="_kcs_KBVInfoArea">
///    <c>KCS_KBVInfoArea</c> as type
/// </param>
/// <param name="_hcmWorker">
///    <c>HcmWorker</c> as type
/// </param>
/// <param name="_dataAreaId">
///    <c>DataAreaId</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
boolean prepareEmailContent(KCS_KBVInfoArea _kcs_KBVInfoArea, HCMWorker _hcmWorker, DataAreaId _dataAreaId = '')
{
    boolean                         retVal;

    KCS_KBVInfoTmp                  locKCS_KBVInfoTmp;
    KCS_KBVBuildingProjectTable     locKCS_KBVBuildingProjectTable;
    KCS_KBVPotentialSalesVolumeTbl  locKCS_KBVPotentialSalesVolumeTbl;
    KCS_KBVPotentialSalesVolumeGLB  locKCS_KBVPotentialSalesVolumeGLB;
    KCS_KBVRequestTable             locKCS_KBVRequestTable;
    KCS_KBVBuildingProjectID        locKCS_KBVBuildingProjectID;

    LanguageId                      locLanguageId;
    Email                           locEmailFrom;
    Email                           locEmailTo;
    str                             locSubject;
    str                             locBody;
    str                             locBodyTmp;
    str                             locBodyTmp2;
    str                             locRow;
    str                             locLink;
    boolean                         locContentToSend;

    date                            locTmpDate;

    DictEnum                        dictEnum;

    container                       containerKCS_KBVBuildingProjectID;

    boolean                         locDataAreaIdAdded;
    smmSalesUnitId                  locsmmSalesUnitId; 

    retVal          = true;

    dictEnum        = new DictEnum(enumNum(KCS_KBVInfoArea));
    locLanguageId   = _hcmWorker.DirPerson().LanguageId;
    locEmailFrom    = kcs_KBVParameters.BVInfoEmailFromDefault;

    if(contract.parmTestEmailTo())
    {
        locEmailTo  = contract.parmTestEmailTo();
    }
    else
    {
        locEmailTo  = _hcmWorker.email();
    }

    //locSubject  = strfmt("@SYS82282", SysLabel::labelId2String2(dictEnum.index2LabelId(_kcs_KBVInfoArea), locLanguageId));
    locSubject  = AVAKBVHelperClass::getEnumValueLabel_KCS_KBVInfoArea(_kcs_KBVInfoArea, locLanguageId);
    if(contract.parmTestEmailTo())
    {
        locSubject  += strfmt(' ' + "@SYS82282", _hcmWorker.name());
        locSubject  += strfmt(' ' + "@SYS82282", _hcmWorker.email());
    }

    containerKCS_KBVBuildingProjectID = conNull();

    switch(_kcs_KBVInfoArea)
    {
        case KCS_KBVInfoArea::BVNew:
            // NEW BUILDING PROJECTS
            while select AVAWorker, KCS_KBVInfoArea, KCS_KBVBuildingProjectID
            from    locKCS_KBVInfoTmp
            group by locKCS_KBVInfoTmp.AVAWorker, locKCS_KBVInfoTmp.KCS_KBVInfoArea, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID
            where   locKCS_KBVInfoTmp.AVAWorker         == _hcmWorker.RecId
                &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea   == _kcs_KBVInfoArea
                join    locKCS_KBVPotentialSalesVolumeGLB
                where   locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVBuildingProjectID      == locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID
                    &&  locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume   >= _hcmWorker.NDX_KBVInfoRevLimit
            {
                locKCS_KBVBuildingProjectTable =  KCS_KBVBuildingProjectTable::find(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);

                if(!conFind(containerKCS_KBVBuildingProjectID, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID))
                {
                    containerKCS_KBVBuildingProjectID += locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID;
                }

                locLink = AVABPHTMLHelper::deepLinkBuildingProject(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);

                locRow      = '';
                locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(locLink, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID));
                locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.KCS_KBVSubject);
                locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.AddressCity);
                locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.AddressCountryRegionId);
                locRow      = AVABPHTMLHelper::htmlTableRow(locRow);

                locBody     += locRow;

                locContentToSend = true;
            }

            locBody = AVABPHTMLHelper::htmlTable(locBody);

            if(locEmailTo && locContentToSend)
            {
                retVal = this.sendBPEmail(  locEmailFrom,
                                            locEmailTo,
                                            locSubject,
                                            locBody     );
                this.prepareEmailLog(   _kcs_KBVInfoArea,
                                        _hcmWorker.RecId,
                                        locEmailTo,
                                        containerKCS_KBVBuildingProjectID   );
            }
            else
            {
                retVal = false;
            }
            break;

        case KCS_KBVInfoArea::RequestNew:
            // NEW REQUESTS / NEW REQUESTS RICO

            locKCS_KBVBuildingProjectID = '';

            while select AVAWorker, KCS_KBVInfoArea, KCS_KBVBuildingProjectID, KCS_KBVDataArea, smmSalesUnitId
            from    locKCS_KBVInfoTmp
            group by    locKCS_KBVInfoTmp.AVAWorker,
                        locKCS_KBVInfoTmp.KCS_KBVInfoArea,
                        locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID,
                        locKCS_KBVInfoTmp.KCS_KBVDataArea,
                        locKCS_KBVInfoTmp.smmSalesUnitId
            where   locKCS_KBVInfoTmp.AVAWorker         == _hcmWorker.RecId
                &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea   == _kcs_KBVInfoArea
            {
                locKCS_KBVBuildingProjectTable      = KCS_KBVBuildingProjectTable::find(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);
                locKCS_KBVPotentialSalesVolumeTbl   = KCS_KBVPotentialSalesVolumeTbl::find(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);

                if(locKCS_KBVBuildingProjectID != locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID)
                {
                    // one heading for each building project
                    locKCS_KBVBuildingProjectID         = locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID;

                    if(!conFind(containerKCS_KBVBuildingProjectID, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID))
                    {
                        containerKCS_KBVBuildingProjectID += locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID;
                    }

                    locBodyTmp  = '';

                    locLink     = AVABPHTMLHelper::deepLinkBuildingProject(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);
                    locRow      = '';
                    locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(locLink, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID));
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.KCS_KBVSubject);
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.AddressCity);
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.AddressCountryRegionId);
                    locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locKCS_KBVPotentialSalesVolumeTbl.KCS_KBVPotentialSalesVolume), 'right');
                    locRow      = AVABPHTMLHelper::htmlTableRow(locRow);
                    locBodyTmp  += locRow;
                    locBodyTmp  = AVABPHTMLHelper::htmlTable(locBodyTmp);

                    locBody     +=  locBodyTmp;
                }

                locBodyTmp      = '';

                locDataAreaIdAdded  = false;
                locsmmSalesUnitId   = '';

                changecompany(locKCS_KBVInfoTmp.KCS_KBVDataArea)
                {
                    while select *
                    from    locKCS_KBVRequestTable
                    where   locKCS_KBVRequestTable.KCS_KBVBuildingProjectID == locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID
                        &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus     == KCS_KBVRequestStatus::Created
                        &&  locKCS_KBVRequestTable.ModifiedDateTime         >= kcs_MinDateTime
                    {
                        locLink     = AVABPHTMLHelper::deepLinkRequest(locKCS_KBVRequestTable.KCS_KBVRequestID);
                        locRow      = '';
                        locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
                        if(locDataAreaIdAdded)
                        {
                            locRow  += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(2));
                        }
                        else
                        {
                            locRow  += AVABPHTMLHelper::htmlTableCell(locKCS_KBVInfoTmp.KCS_KBVDataArea);
                            locDataAreaIdAdded = true;
                        }
                        locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
                        if(locsmmSalesUnitId)
                        {
                            locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(2));
                        }
                        else
                        {
                            locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVInfoTmp.smmSalesUnitId);
                            locsmmSalesUnitId = locKCS_KBVInfoTmp.smmSalesUnitId;
                        }
                        locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
                        locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(locLink, locKCS_KBVRequestTable.KCS_KBVRequestID));
                        locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVRequestTable.displayOrganizationName());
                        locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVRequestTable.displayPersonName());
                        if(locKCS_KBVRequestTable.KCS_KBVDeliveryDate == dateNull())
                        {
                            locRow  += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(1));
                        }
                        else
                        {
                            locRow  += AVABPHTMLHelper::htmlTableCell(SysLabel::labelId2String2(literalStr("@NDX:NXATenderClosingDate"), locLanguageId) + ': ');
                        }
                        locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locKCS_KBVRequestTable.KCS_KBVDeliveryDate));
                        locRow      = AVABPHTMLHelper::htmlTableRow(locRow);
                        locBodyTmp  += locRow;

                        locContentToSend = true;
                    }
                    locBodyTmp  = AVABPHTMLHelper::htmlTable(locBodyTmp);
                }

                locBody     +=  locBodyTmp;
            }

            locBody = AVABPHTMLHelper::htmlTable(locBody);
            if(locEmailTo && locContentToSend)
            {
                retVal = this.sendBPEmail(  locEmailFrom,
                                            locEmailTo,
                                            locSubject,
                                            locBody     );
                this.prepareEmailLog(   _kcs_KBVInfoArea,
                                        _hcmWorker.RecId,
                                        locEmailTo,
                                        containerKCS_KBVBuildingProjectID   );
            }
            else
            {
                retVal = false;
            }
            break;

        case KCS_KBVInfoArea::QuotationNew:
            //NEW QUOTATIONS
            locKCS_KBVBuildingProjectID = '';

            while select AVAWorker, KCS_KBVInfoArea, KCS_KBVBuildingProjectID, smmSalesUnitId
            from    locKCS_KBVInfoTmp
            group by    locKCS_KBVInfoTmp.AVAWorker, 
                        locKCS_KBVInfoTmp.KCS_KBVInfoArea, 
                        locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID,
                        locKCS_KBVInfoTmp.KCS_KBVDataArea,
                        locKCS_KBVInfoTmp.smmSalesUnitId
            where   locKCS_KBVInfoTmp.AVAWorker         == _hcmWorker.RecId
                &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea   == _kcs_KBVInfoArea
                join    locKCS_KBVPotentialSalesVolumeGLB
                where   locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVBuildingProjectID      == locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID
                    &&  locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume   >= _hcmWorker.NDX_KBVInfoRevLimit
            {
                if(locKCS_KBVBuildingProjectID != locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID)
                {
                    // one heading for each building project
                    locKCS_KBVBuildingProjectID         = locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID;

                    locKCS_KBVBuildingProjectTable      = KCS_KBVBuildingProjectTable::find(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);
                    locKCS_KBVPotentialSalesVolumeTbl   = KCS_KBVPotentialSalesVolumeTbl::find(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);

                    if(!conFind(containerKCS_KBVBuildingProjectID, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID))
                    {
                        containerKCS_KBVBuildingProjectID += locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID;
                    }

                    locBodyTmp  = '';

                    locLink     = AVABPHTMLHelper::deepLinkBuildingProject(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);
                    locRow      = '';
                    locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(locLink, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID));
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.KCS_KBVSubject);
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.AddressCity);
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.AddressCountryRegionId);
                    locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locKCS_KBVPotentialSalesVolumeTbl.KCS_KBVPotentialSalesVolume), 'right');
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVPotentialSalesVolumeTbl.CurrencyCode);
                    locRow      = AVABPHTMLHelper::htmlTableRow(locRow);
                    locBodyTmp  += locRow;
                    locBody     += AVABPHTMLHelper::htmlTable(locBodyTmp);
                }

                locBodyTmp  = '';

                locBodyTmp  = this.avaGetRows_NewQuotation( locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID,
                                                            locKCS_KBVInfoTmp.KCS_KBVDataArea,
                                                            locKCS_KBVInfoTmp.smmSalesUnitId            );

                if(locBodyTmp != '')
                {
                    locContentToSend = true;
                }

                locBodyTmp  = AVABPHTMLHelper::htmlTable(locBodyTmp);

                locBody     +=  locBodyTmp;
            }

            locBody = AVABPHTMLHelper::htmlTable(locBody);

            if(locEmailTo && locContentToSend)
            {
                retVal = this.sendBPEmail(  locEmailFrom,
                                            locEmailTo,
                                            locSubject,
                                            locBody     );
                this.prepareEmailLog(   _kcs_KBVInfoArea,
                                        _hcmWorker.RecId,
                                        locEmailTo,
                                        containerKCS_KBVBuildingProjectID   );
            }
            else
            {
                retVal = false;
            }
            break;

        case KCS_KBVInfoArea::QuotationChanged:
            //CHANGED QUOTATIONS
            while select AVAWorker, KCS_KBVInfoArea, KCS_KBVBuildingProjectID, KCS_KBVDataArea, smmSalesUnitId
            from    locKCS_KBVInfoTmp
            group by    locKCS_KBVInfoTmp.AVAWorker, 
                        locKCS_KBVInfoTmp.KCS_KBVInfoArea, 
                        locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID,
                        locKCS_KBVInfoTmp.KCS_KBVDataArea,
                        locKCS_KBVInfoTmp.smmSalesUnitId
            where   locKCS_KBVInfoTmp.AVAWorker         == _hcmWorker.RecId
                &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea   == _kcs_KBVInfoArea
                join    locKCS_KBVPotentialSalesVolumeGLB
                where   locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVBuildingProjectID      == locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID
                    &&  locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume   >= _hcmWorker.NDX_KBVInfoRevLimit
            {
                if(locKCS_KBVBuildingProjectID != locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID)
                {
                    // one heading for each building project
                    locKCS_KBVBuildingProjectID = locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID;
                    if(!conFind(containerKCS_KBVBuildingProjectID, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID))
                    {
                        containerKCS_KBVBuildingProjectID += locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID;
                    }

                    locKCS_KBVBuildingProjectTable      = KCS_KBVBuildingProjectTable::find(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);
                    locKCS_KBVPotentialSalesVolumeTbl   = KCS_KBVPotentialSalesVolumeTbl::find(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);

                    locBodyTmp2 = '';

                    locBodyTmp  = '';
                    locLink     = AVABPHTMLHelper::deepLinkBuildingProject(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);
                    locRow      = '';
                    locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(locLink, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID));
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.KCS_KBVSubject);
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.AddressCity);
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.AddressCountryRegionId);
                    locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locKCS_KBVPotentialSalesVolumeTbl.KCS_KBVPotentialSalesVolume), 'right');
                    locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVPotentialSalesVolumeTbl.CurrencyCode);
                    locRow      = AVABPHTMLHelper::htmlTableRow(locRow);
                    locBodyTmp  = AVABPHTMLHelper::htmlTable(locRow);

                    locBodyTmp2 = locBodyTmp;   // header
                }
                else
                {
                    locBodyTmp2 = '';           // dont keep the same header
                }

                locBodyTmp = '';
                locBodyTmp = this.avaGetRows_QuotationChanged(  locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID,
                                                                locKCS_KBVInfoTmp.KCS_KBVDataArea,
                                                                locKCS_KBVInfoTmp.smmSalesUnitId            );

                if(locBodyTmp != '')
                {
                    locBody += locBodyTmp;
                    locContentToSend = true;
                }

                if(locBody)
                {
                    locBody = locBodyTmp2 + locBody;    // add header to details
                }
                else
                {
                    locBody = '';                       // no details, nothing to send
                }
            }

            if(locEmailTo && locContentToSend)
            {
                retVal = this.sendBPEmail(  locEmailFrom,
                                            locEmailTo,
                                            locSubject,
                                            locBody     );
                this.prepareEmailLog(   _kcs_KBVInfoArea,
                                        _hcmWorker.RecId,
                                        locEmailTo,
                                        containerKCS_KBVBuildingProjectID   );
            }
            else
            {
                retVal = false;
            }
            break;

        case KCS_KBVInfoArea::BVChanged:
            //CHANGED BUILDING PROJECTS
            while select AVAWorker, KCS_KBVInfoArea, KCS_KBVBuildingProjectID
            from    locKCS_KBVInfoTmp
            group by locKCS_KBVInfoTmp.AVAWorker, locKCS_KBVInfoTmp.KCS_KBVInfoArea, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID
            where   locKCS_KBVInfoTmp.AVAWorker         == _hcmWorker.RecId
                &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea   == _kcs_KBVInfoArea
                join    locKCS_KBVPotentialSalesVolumeGLB
                where   locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVBuildingProjectID      == locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID
                    &&  locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume   >= _hcmWorker.NDX_KBVInfoRevLimit
            {
                if(!conFind(containerKCS_KBVBuildingProjectID, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID))
                {
                    containerKCS_KBVBuildingProjectID += locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID;
                }

                locBodyTmp  = '';

                locKCS_KBVBuildingProjectTable      = KCS_KBVBuildingProjectTable::find(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);
                locKCS_KBVPotentialSalesVolumeTbl   = KCS_KBVPotentialSalesVolumeTbl::find(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);

                locLink     = AVABPHTMLHelper::deepLinkBuildingProject(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);
                locRow      = '';
                locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(locLink, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID));
                locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.KCS_KBVSubject);
                locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.AddressCity);
                locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVBuildingProjectTable.AddressCountryRegionId);
                locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locKCS_KBVPotentialSalesVolumeTbl.KCS_KBVPotentialSalesVolume));
                locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVPotentialSalesVolumeTbl.CurrencyCode);
                locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locKCS_KBVBuildingProjectTable.KCS_KBVStatus));
                locRow      = AVABPHTMLHelper::htmlTableRow(locRow);
                locBodyTmp  += locRow;
                locBodyTmp  = AVABPHTMLHelper::htmlTable(locBodyTmp);

                locBody     += locBodyTmp;

                locBodyTmp  = '';

                locBodyTmp  = this.avaGetRows_BVChanged(locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID, 
                                                        locLanguageId                               );

                locBody     += locBodyTmp;

                locContentToSend = true;
            }

            locBody = AVABPHTMLHelper::htmlTable(locBody);

            if(locEmailTo && locContentToSend)
            {
                retVal = this.sendBPEmail(  locEmailFrom,
                                            locEmailTo,
                                            locSubject,
                                            locBody     );
                this.prepareEmailLog(   _kcs_KBVInfoArea,
                                        _hcmWorker.RecId,
                                        locEmailTo,
                                        containerKCS_KBVBuildingProjectID   );
            }
            else
            {
                retVal = false;
            }
            break;

        case KCS_KBVInfoArea::ActivityNewChanged :
            //NEW OR CHANGED ACTIVITIES
            // send activities
            if(contract.parmNewChangedActivities() && _hcmWorker.NDX_KBVSendActivities)
            {
                //locTmpDate =  DateTimeUtil::date(kcs_KBVParameters.NDX_KBVInfoDateTime);
                locTmpDate  = kcs_MinDate;

                //ACTIVITIES
                while select AVAWorker, KCS_KBVInfoArea, KCS_KBVBuildingProjectID
                from    locKCS_KBVInfoTmp
                group by locKCS_KBVInfoTmp.AVAWorker, locKCS_KBVInfoTmp.KCS_KBVInfoArea, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID
                where   locKCS_KBVInfoTmp.AVAWorker         == _hcmWorker.RecId
                    &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea   == _kcs_KBVInfoArea
                {
                    locBodyTmp  = '';
                    locBodyTmp  = this.avaGetRows_ActivityNewChanged(_hcmWorker, locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID);

                    if(locBodyTmp != '')
                    {
                        locContentToSend = true;
                    }

                    locBody += locBodyTmp;
                }
            }
            if(locBody)
            {
                locBody = AVABPHTMLHelper::htmlTable(locBody);
            }
            if(locEmailTo && locContentToSend)
            {
                retVal = this.sendBPEmail(  locEmailFrom,
                                            locEmailTo,
                                            locSubject,
                                            locBody     );
                this.prepareEmailLog(   _kcs_KBVInfoArea,
                                        _hcmWorker.RecId,
                                        locEmailTo,
                                        containerKCS_KBVBuildingProjectID   );
            }
            else
            {
                retVal = false;
            }
            break;
    }
    return retVal;
}

 /// <summary>
 ///     AVA <c>avaGetRows_NewQuotation</c> method.
 ///     moved method out of prepareEmailContent method for nested loop reasons
 /// </summary>
 /// <param name="_buildingProjectId">
 ///     <c>KCS_KBVBuildingProjectID</c> as type
 /// </param>
 /// <param name="_dataAreaId">
 ///     <c>DataAreaId</c> as type
 /// </param>
 /// <param name="_smmSalesUnitId">
 ///     <c>smmSalesUnitId</c> as type
 /// </param>
 /// <returns>
 ///     <c>AVASalesLineBackOrderTmp</c> as return value
 /// </returns>
public str avaGetRows_NewQuotation(  KCS_KBVBuildingProjectID    _buildingProjectId,
                                     DataAreaId                  _dataAreaId,
                                     smmSalesUnitId              _smmSalesUnitId     )
 {
     str                 locLink, locRow, locBodyTmp;
     SalesQuotationTable locSalesQuotationTable;
     smmSalesUnitId      locsmmSalesUnitId;
     boolean             locDataAreaIdAdded;

     changecompany(_dataAreaId)
     {
         while select locSalesQuotationTable
         where   locSalesQuotationTable.KCS_KBVBuildingProjectID == _buildingProjectId
             &&  locSalesQuotationTable.QuotationStatus          != SalesQuotationStatus::Created
             &&  locSalesQuotationTable.createdDateTime          >= kcs_MinDateTime
             &&  locSalesQuotationTable.SalesUnitId              == _smmSalesUnitId
         {
             locLink     = AVABPHTMLHelper::deepLinkQuotation(locSalesQuotationTable.QuotationId);
             locRow      = '';
             locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
             if(locDataAreaIdAdded)
             {
                 locRow  += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(2));
             }
             else
             {
                 locRow  += AVABPHTMLHelper::htmlTableCell(_dataAreaId);
             }
             locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
             if(locsmmSalesUnitId)
             {
                 locRow  += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(2));
                 locsmmSalesUnitId = _smmSalesUnitId;
             }
             else
             {
                 locRow  += AVABPHTMLHelper::htmlTableCell(locSalesQuotationTable.SalesUnitId);
             }
             locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(2));
             locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(locLink, locSalesQuotationTable.QuotationId));
             locRow      += AVABPHTMLHelper::htmlTableCell(locSalesQuotationTable.QuotationName);
             locRow      += AVABPHTMLHelper::htmlTableCell(locSalesQuotationTable.contactPersonName());
             //locRow      += AVABPHTMLHelper::htmlTableCell(HcmWorker::find(locSalesQuotationTable.WorkerSalesTaker).name());
             locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locSalesQuotationTable.KCS_QuotationAmount), 'right');
             locRow      += AVABPHTMLHelper::htmlTableCell(locSalesQuotationTable.CurrencyCode);
             locRow      = AVABPHTMLHelper::htmlTableRow(locRow);
             locBodyTmp  += locRow;
         }
     }

     return locBodyTmp;
 }

/// <summary>
///     AVA <c>avaGetRows_QuotationChanged</c> method.
///     moved method out of prepareEmailContent method for nested loop reasons
/// </summary>
/// <param name="_buildingProjectId">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_dataAreaId">
///     <c>DataAreaId</c> as type
/// </param>
/// <param name="_smmSalesUnitId">
///     <c>smmSalesUnitId</c> as type
/// </param>
/// <returns>
///     <c>AVASalesLineBackOrderTmp</c> as return value
/// </returns>
public str avaGetRows_QuotationChanged( KCS_KBVBuildingProjectID    _buildingProjectId,
                                        DataAreaId                  _dataAreaId,
                                        smmSalesUnitId              _smmSalesUnitId     )
{
    SalesQuotationTable     locSalesQuotationTable;
    CustQuotationJour       locCustQuotationJourPrevVersion, locCustQuotationJour;
    QuotationIdBase         locQuotationIdBase;
    AVASpecialDiscQuotation locAVASpecialDiscQuotation;
    Amount                  locTotalSD1, locTotalSD2, locBase1, locBase2;
    str                     locBody, locBodyTmp, locBodyTmp3, locBodyTmp4, locLink, locRow, locRowTmp;
    smmSalesUnitId          locsmmSalesUnitId;
    AVABPInfoDateTime       locKCS_MinDateTime;
    boolean                 locDataAreaIdAdded;

    locKCS_MinDateTime = kcs_MinDateTime;

    changecompany(_dataAreaId)
    {
        while select locSalesQuotationTable
        where   locSalesQuotationTable.KCS_KBVBuildingProjectID == _buildingProjectId
            &&  locSalesQuotationTable.SalesUnitId              == _smmSalesUnitId
            &&  locSalesQuotationTable.modifiedDateTime         >= locKCS_MinDateTime
            &&  locSalesQuotationTable.createdDateTime          < locKCS_MinDateTime
        {
            locQuotationIdBase = locSalesQuotationTable.lastQuotation();

            select firstonly locCustQuotationJour
            where   locCustQuotationJour.QuotationDocNum == locQuotationIdBase;

            if(locCustQuotationJour.RecId)
            {
                locCustQuotationJourPrevVersion = locCustQuotationJour.avaPreviousCustQuotationJour();
            }

            locBodyTmp3 = '';
            locBodyTmp4 = '';

            if(locCustQuotationJourPrevVersion.RecId)
            {
                locBodyTmp  = '';
                locLink     = AVABPHTMLHelper::deepLinkQuotation(locSalesQuotationTable.QuotationId);
                locRow      = '';
                locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
                if(locDataAreaIdAdded)
                {
                    locRow  += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(2));
                }
                else
                {
                    locRow  += AVABPHTMLHelper::htmlTableCell(_dataAreaId);
                    locDataAreaIdAdded = true;
                }
                locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
                if(locsmmSalesUnitId)
                {
                    locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(2));
                }
                else
                {
                    locRow      += AVABPHTMLHelper::htmlTableCell(locSalesQuotationTable.SalesUnitId);
                    locsmmSalesUnitId = _smmSalesUnitId;
                }
                locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(2));
                locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(locLink, locSalesQuotationTable.QuotationId));
                locRow      += AVABPHTMLHelper::htmlTableCell(locSalesQuotationTable.QuotationName);
                locRow      += AVABPHTMLHelper::htmlTableCell(locSalesQuotationTable.contactPersonName());
                //locRow      += AVABPHTMLHelper::htmlTableCell(HcmWorker::find(locSalesQuotationTable.WorkerSalesTaker).name());
                locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locSalesQuotationTable.QuotationStatus));
                locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locSalesQuotationTable.KCS_StatusId));
                locRow      = AVABPHTMLHelper::htmlTableRow(locRow);
                locBodyTmp  = AVABPHTMLHelper::htmlTable(locRow);

                locBodyTmp3 = locBodyTmp;   // details part 1

                locBodyTmp = '';
                locRow      = '';

                locRowTmp   = '';
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(36));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", "@SYS128676")); //Buchungsdatum
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locCustQuotationJour.QuotationDate));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locCustQuotationJourPrevVersion.QuotationDate));
                locRowTmp   = AVABPHTMLHelper::htmlTableRow(locRowTmp);
                locRow      += locRowTmp;

                locRowTmp   = '';
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(36));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", "@NDX:NXAGrossValueOfGoods")); //Warenwert Brutto
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locCustQuotationJour.KCS_QuotationAmount), 'right');
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locCustQuotationJourPrevVersion.KCS_QuotationAmount), 'right');
                locRowTmp   = AVABPHTMLHelper::htmlTableRow(locRowTmp);
                locRow      += locRowTmp;

                locRowTmp   = '';
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(36));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", "@NDX:NDXSpecialDiscount")); //Sonderrabatte
                /*
                locAVASpecialDiscQuotation = AVASpecialDiscQuotation::find( locCustQuotationJour.KCS_QuotationId);
                locTotal1   = 0.0;
                locTotal1   += locCustQuotationJour.KCS_QuotationAmount * locAVASpecialDiscQuotation.SpecialDiscountPct1 / 100;
                locTotal1   += locCustQuotationJour.KCS_QuotationAmount * locAVASpecialDiscQuotation.SpecialDiscountPct2 / 100;
                locTotal1   += locCustQuotationJour.KCS_QuotationAmount * locAVASpecialDiscQuotation.SpecialDiscountPct3 / 100;
                locTotal1   = locTotal1 * locAVASpecialDiscQuotation.AllDiscountFactor;
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locTotal1), 'right');
                locAVASpecialDiscQuotation = AVASpecialDiscQuotation::find( locCustQuotationJourPrevVersion.KCS_QuotationId);
                locTotal2   = 0.0;
                locTotal2   += locCustQuotationJourPrevVersion.KCS_QuotationAmount * locAVASpecialDiscQuotation.SpecialDiscountPct1 / 100;
                locTotal2   += locCustQuotationJourPrevVersion.KCS_QuotationAmount * locAVASpecialDiscQuotation.SpecialDiscountPct2 / 100;
                locTotal2   += locCustQuotationJourPrevVersion.KCS_QuotationAmount * locAVASpecialDiscQuotation.SpecialDiscountPct3 / 100;
                locTotal2   = locTotal2 * locAVASpecialDiscQuotation.AllDiscountFactor;
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locTotal2), 'right');
                */
                locBase1    = locCustQuotationJour.KCS_QuotationAmount;
                locBase1    = locCustQuotationJour.displayAVABaseAmount();
                locTotalSD1 = locCustQuotationJour.avaSpecialDiscAmount(true);
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locTotalSD1), 'right');
                locBase2    = locCustQuotationJourPrevVersion.KCS_QuotationAmount;
                locBase2    = locCustQuotationJourPrevVersion.displayAVABaseAmount();
                locTotalSD2 = locCustQuotationJourPrevVersion.avaSpecialDiscAmount(true);
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locTotalSD2), 'right');
                locRowTmp   = AVABPHTMLHelper::htmlTableRow(locRowTmp);
                locRow      += locRowTmp;

                locRowTmp   = '';
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(36));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", "@SYS58659"));  // Summe
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locCustQuotationJour.KCS_QuotationAmount - locTotalSD1), 'right');
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locCustQuotationJourPrevVersion.KCS_QuotationAmount - locTotalSD2), 'right');
                locRowTmp   = AVABPHTMLHelper::htmlTableRow(locRowTmp);
                locRow      += locRowTmp;

                locRowTmp   = '';
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(4));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(36));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", "@SYS4006602")); //Gültig bis
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locCustQuotationJour.RespiteDate));
                locRowTmp   += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locCustQuotationJourPrevVersion.RespiteDate));
                locRowTmp   = AVABPHTMLHelper::htmlTableRow(locRowTmp);
                locRow      += locRowTmp;

                locBodyTmp  = AVABPHTMLHelper::htmlTable(locRow);

                locBodyTmp4 = locBodyTmp;   // details part 2
            }
            locBodyTmp = locBodyTmp3 + locBodyTmp4;  // details

            if(locBodyTmp)
            {
                locBody     += locBodyTmp;
            }
        }
    }

    return locBody;
}

/// <summary>
///     AVA <c>avaGetRows_BVChanged</c> method.
///     moved method out of prepareEmailContent method for nested loop reasons
/// </summary>
/// <param name="_buildingProjectId">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_languageId">
///     <c>LanguageId</c> as type
/// </param>
/// <returns>
///     <c>str</c> as return value
/// </returns>
public str avaGetRows_BVChanged(KCS_KBVBuildingProjectID    _buildingProjectId,
                                LanguageId                  _languageId         )
{
    str                             locRow, locBody, locBodyTmp;
    KCS_KBVRelationsToBV            locKCS_KBVRelationsToBV;
    KCS_KBVResponsibilitiesTable    locKCS_KBVResponsibilitiesTable;

    while select locKCS_KBVRelationsToBV
    where   locKCS_KBVRelationsToBV.KCS_KBVBuildingProjectID == _buildingProjectId
                    //ToDo: && ...
    {
        locRow      = '';
        locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVRelationsToBV.KCS_KBVRelationID);
        locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVRelationsToBV.dirPartyTablePrefered().Name);
        locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVRelationsToBV.displayContactPersonName());
        locRow      = AVABPHTMLHelper::htmlTableRow(locRow);
        locBodyTmp  += locRow;
    }
    locBodyTmp  = AVABPHTMLHelper::htmlTable(locBodyTmp);

    locBody     +=  locBodyTmp;

    locBodyTmp  = '';

    while select locKCS_KBVResponsibilitiesTable
    where   locKCS_KBVResponsibilitiesTable.KCS_KBVBuildingProjectID == _buildingProjectId
    {
        locRow      = '';
        locRow      += AVABPHTMLHelper::htmlTableCell(locKCS_KBVResponsibilitiesTable.smmResponsibilityId);
        locRow      += AVABPHTMLHelper::htmlTableCell(HcmWorker::find(locKCS_KBVResponsibilitiesTable.smmWorker).name());
        if(locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate == dateNull())
        {
            locRow   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlSpace(1));
        }
        else
        {
            locRow      += AVABPHTMLHelper::htmlTableCell(SysLabel::labelId2String2(literalStr("@NDX:NXAEndsOn"), _languageId) + ': ');
        }
        locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate));
        locRow      = AVABPHTMLHelper::htmlTableRow(locRow);
        locBodyTmp  += locRow;
    }
    locBodyTmp  = AVABPHTMLHelper::htmlTable(locBodyTmp);

    locBody  += locBodyTmp;

    return locBody;
}

/// <summary>
/// moved method out of prepareEmailContent method for nested loop reasons
/// </summary>
/// <param name = "_hcmWorker">HCMWorker</param>
/// <param name = "_buildingProjectId">KCS_KBVBuildingProjectId</param>
/// <returns>str</returns>
public str avaGetRows_ActivityNewChanged(HcmWorker _hcmWorker, KCS_KBVBuildingProjectID _buildingProjectId)
{
    str                     locBody, locBodyTmp, locRow, locLink;
    container               containerKCS_KBVBuildingProjectID;
    KCS_KBVActivitiesForBP  locKCS_KBVActivitiesForBP;
    smmActivities           locSMMActivities;

    while select crosscompany : allBPCompanies locKCS_KBVActivitiesForBP
    where   locKCS_KBVActivitiesForBP.KCS_KBVBuildingProjectID  == _buildingProjectId
        join    locSMMActivities
        where   locSMMActivities.ActivityNumber  == locKCS_KBVActivitiesForBP.smmActivityNumber
    {
        if( (       locSMMActivities.ResponsibleWorker      == _hcmWorker.RecId
                &&  (   locSMMActivities.CreatedDateTime    >= kcs_MinDateTime  
                    ||  locSMMActivities.ModifiedDateTime   >= kcs_MinDateTime  )   )
            ||  (   locSMMActivities.AVAFieldWorker         == _hcmWorker.RecId
                &&  (   locSMMActivities.CreatedDateTime    >= kcs_MinDateTime  
                    ||  locSMMActivities.ModifiedDateTime   >= kcs_MinDateTime  )   )   )
        {
            if(!conFind(containerKCS_KBVBuildingProjectID, _buildingProjectId))
            {
                containerKCS_KBVBuildingProjectID += _buildingProjectId;
            }

            locBodyTmp  = '';

            locRow      = '';
            locRow      += AVABPHTMLHelper::htmlTableCell(strFmt("@SYS82282", locSMMActivities.endDate()));
            locLink     = AVABPHTMLHelper::deepLinkSmmActivities(locKCS_KBVActivitiesForBP.smmActivityNumber);
            locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(locLink, locKCS_KBVActivitiesForBP.smmActivityNumber));
            locLink     = AVABPHTMLHelper::deepLinkBuildingProject(_buildingProjectId);
            locRow      += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(locLink, _buildingProjectId));
            locRow      += AVABPHTMLHelper::htmlTableCell(locSMMActivities.Purpose);
            locRow      += AVABPHTMLHelper::htmlTableCell(HcmWorker::find(locSMMActivities.ResponsibleWorker).name());
            locRow      = AVABPHTMLHelper::htmlTableRow(locRow);
            locBodyTmp  = locRow;

            locBody     += locBodyTmp;
        }

    }

    return locBody;
}

/// <summary>
///    AVA <c>sendBPEmail</c> method.
/// </summary>
/// <param name="_emailFrom">
///    <c>Email</c> as type
/// </param>
/// <param name="_emailTo">
///    <c>Email</c> as type
/// </param>
/// <param name="_subject">
///    <c>str</c> as type
/// </param>
/// <param name="_body">
///    <c>str</c> as type
/// </param>
/// <param name="_emailSendingActivated">
///    <c>boolean</c> as type
/// </param>
/// <param name="_infoMessageActivated">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
boolean sendBPEmail(Email   _emailFrom, 
                    Email   _emailTo,
                    str     _subject,
                    str     _body,
                    boolean _emailSendingActivated  = true,
                    boolean _infoMessageActivated   = false)
{
    boolean                 retVal;

    SysMailerMessageBuilder messageBuilder;

    str                     mailBody;

    mailBody = _body;

    //mailBody += AVABPHTMLHelper::htmlBreak(2);  // automatic paragraph is generated in eamil process

    mailBody += strReplace(kcs_KBVParameters.AVAFooterMemo, '\n', AVABPHTMLHelper::htmlBreak(1));

    retVal = true;

    if(_emailSendingActivated)
    {
        messageBuilder = new SysMailerMessageBuilder();

        try
        {
            messageBuilder.setBody(mailBody, true);
            messageBuilder.setSubject(_subject);
            messageBuilder.addTo(_emailTo);
            // Note: not calling setFrom() defaults to the current user for SMTP client, whereas
            // when sent to Outlook any setFrom() value will be ignored since profiles on the client are used
            messageBuilder.setFrom(_emailFrom);

            // Open the generated email in the configured client
            if(lJobMode)
            {
                // Try using sendNonInteractive method too
                retVal = SysMailerFactory::sendNonInteractive(messageBuilder.getMessage());
            }
            else
            {
                // Sends a message interactively, allowing the user to view and modify the message before
                retVal = SysMailerFactory::sendInteractive(messageBuilder.getMessage());
            }
            this.insertEmailLog();
        }
        catch (Exception::Error)
        {
            throw error(strFmt("@NDX:NXABPInfoEmailSubjectNotSent", _emailTo + ':' + _subject));
        }
    }
    if(_infoMessageActivated)
    {
        info(strFmt("@NDX:NXAEmailContentInfo", _emailFrom,
                                                _emailTo,
                                                _subject,
                                                _body       )   );
    }

    return retVal;                     
}

/// <summary>
///     AVA <c>prepareEmailLog</c> method.
/// </summary>
/// <param name="_kcs_KBVInfoArea">
///     <c>KCS_KBVInfoArea</c> as type
/// </param>
/// <param name="_hcmWorkerRecId">
///     <c>HCMWorkerRecId</c> as type
/// </param>
/// <param name="_email">
///     <c>Email</c> as type
/// </param>
/// <param name="_containerKCS_KBVBuildingProjectID">
///     <c>container</c> as type
/// </param>
public void prepareEmailLog(KCS_KBVInfoArea             _kcs_KBVInfoArea,
                            HCMWorkerRecId              _hcmWorkerRecId,
                            Email                       _email,
                            container                   _containerKCS_KBVBuildingProjectID)
{
    logNDX_KBVEmailSend.clear();
    logNDX_KBVEmailSend.NDX_KBVMail                 = NDX_KBVMail::KBV_Info;

    logNDX_KBVEmailSend.KCS_KBVInfoArea             = _kcs_KBVInfoArea;
    logNDX_KBVEmailSend.AVAWorker                   = _hcmWorkerRecId;
    logNDX_KBVEmailSend.Email                       = _email;

    if(conLen(_containerKCS_KBVBuildingProjectID) == 1)
    {
        logNDX_KBVEmailSend.KCS_KBVBuildingProjectID    = conPeek(_containerKCS_KBVBuildingProjectID, 1);
    }
    else
    {
        logNDX_KBVEmailSend.KCS_KBVBuildingProjectID    = '';
    }
}

/// <summary>
///     AVA <c>insertEmailLog</c> method.
/// </summary>
public void insertEmailLog()
{
    logNDX_KBVEmailSend.createProt( logNDX_KBVEmailSend.Email, 
                                    NDX_KBVMail::KBV_Info,
                                    logNDX_KBVEmailSend.KCS_KBVBuildingProjectID,
                                    logNDX_KBVEmailSend.AVAWorker,
                                    logNDX_KBVEmailSend.KCS_KBVInfoArea             );
}
